#!/usr/bin/env bash
# shellcheck source-path=SCRIPTDIR
# detect-api-flags.sh — Read API Manager flags from settings.properties and resolve RAML coordinates.
#
# GENERATED by tests/parity/extract_inline_bash.py — do not hand-edit (change the Azure source or
# the extractor, then run it with --write). Extracted from the Azure DevOps inline step:
#   source : platforms/azure-devops/mulesoft-pipeline-templates/pipelines/templates/steps/create-api-components.yml
#   step   : "Detect API Flags & RAML Coordinates" (Bash@3 inline)
# The body is that step verbatim, except: ##vso commands -> ci-shim calls, Azure predefined
# variables -> ci-shim normalizers, and $(...) / ${{ parameters.* }} macros -> the MDF_* inputs below.
#
# Inputs (environment):
#   MDF_ARTIFACTS_DIR      <- ${{ parameters.artifactsDir }}  [default: $(Pipeline.Workspace)/mule-artifacts]
#   MDF_ARTIFACT_ID        <- ${{ parameters.artifactId }}  [required]
#   MDF_CLASSIFIER         <- ${{ parameters.classifier }}  [default: mule-application]
#   MDF_ENV_SETTINGS_PATH  <- ${{ parameters.envSettingsPath }}  [required]
# Outputs: IS_API (output), APPLY_POLICIES (output), APPLY_SLA (output), APPLY_CONTRACTS (output), ramlGroupId (output), ramlArtifactId (output), ramlVersion (output), policiesPath (output), slaTiersPath (output), contractsPath (output)

# shellcheck source=lib/ci-shim.sh
source "$(dirname "${BASH_SOURCE[0]}")/lib/ci-shim.sh"

: "${MDF_ARTIFACTS_DIR=$(ci_pipeline_workspace)/mule-artifacts}"
: "${MDF_ARTIFACT_ID?MDF_ARTIFACT_ID is required (Azure parameter artifactId)}"
: "${MDF_CLASSIFIER=mule-application}"
: "${MDF_ENV_SETTINGS_PATH?MDF_ENV_SETTINGS_PATH is required (Azure parameter envSettingsPath)}"

# >>> extracted body
ARTIFACTS_DIR="${MDF_ARTIFACTS_DIR}"
ARTIFACT_ID="${MDF_ARTIFACT_ID}"
CLASSIFIER="${MDF_CLASSIFIER}"
ENV_SETTINGS_PATH="$(ci_pipeline_workspace)/s/${MDF_ENV_SETTINGS_PATH}"
JAR_FILE="$ARTIFACTS_DIR/${ARTIFACT_ID}-${CLASSIFIER}.jar"
EXTRACT_DIR="$ARTIFACTS_DIR/extracted"
APP_NAME="$(ci_repo_name)"

echo "[DEBUG] ============================================"
echo "[DEBUG] CREATE API COMPONENTS - FLAG DETECTION START"
echo "[DEBUG] ============================================"
echo "[DEBUG] Parameters:"
echo "[DEBUG]   artifactsDir=$ARTIFACTS_DIR"
echo "[DEBUG]   artifactId=$ARTIFACT_ID"
echo "[DEBUG]   classifier=$CLASSIFIER"
echo "[DEBUG]   envSettingsPath=$ENV_SETTINGS_PATH"
echo "[DEBUG]   appName=$APP_NAME"
echo "[DEBUG]   JAR_FILE=$JAR_FILE"
echo "[DEBUG]   EXTRACT_DIR=$EXTRACT_DIR"
echo "[DEBUG] ============================================"

# Ensure JAR is already extracted (done during pre-deploy)
if [[ ! -d "$EXTRACT_DIR" ]]; then
  echo "[DEBUG] EXTRACT_DIR does not exist, extracting JAR..."
  echo "Extracting JAR for RAML detection..."
  mkdir -p "$EXTRACT_DIR"
  unzip -o "$JAR_FILE" -d "$EXTRACT_DIR" > /dev/null
else
  echo "[DEBUG] EXTRACT_DIR already exists (from pre-deploy step)"
fi

# --- Read flags from settings.properties (env-settings repo) ---
SETTINGS_FILE="${ENV_SETTINGS_PATH}/${APP_NAME}/settings.properties"
IS_API="false"
APPLY_POLICIES="false"
APPLY_SLA="false"
APPLY_CONTRACTS="false"

echo "[DEBUG] Looking for settings at: $SETTINGS_FILE"
if [[ -f "$SETTINGS_FILE" ]]; then
  echo "[DEBUG] settings.properties found. Full content:"
  echo "[DEBUG] $(cat "$SETTINGS_FILE")"
  IS_API=$(grep '^is.api.manager=' "$SETTINGS_FILE" | cut -d'=' -f2 | tr '[:upper:]' '[:lower:]')
  APPLY_POLICIES=$(grep '^apply.policies=' "$SETTINGS_FILE" | cut -d'=' -f2 | tr '[:upper:]' '[:lower:]')
  APPLY_SLA=$(grep '^apply.sla=' "$SETTINGS_FILE" | cut -d'=' -f2 | tr '[:upper:]' '[:lower:]')
  APPLY_CONTRACTS=$(grep '^apply.contracts=' "$SETTINGS_FILE" | cut -d'=' -f2 | tr '[:upper:]' '[:lower:]')
  echo "Flags from settings.properties: is.api.manager=$IS_API, apply.policies=$APPLY_POLICIES, apply.sla=$APPLY_SLA, apply.contracts=$APPLY_CONTRACTS"
else
  echo "[DEBUG] settings.properties NOT FOUND at: $SETTINGS_FILE"
  echo "[DEBUG] Listing env-settings path: $(ls -la "${ENV_SETTINGS_PATH}/${APP_NAME}/" 2>&1)"
  ci_log_warning "settings.properties not found at: $SETTINGS_FILE. All API flags default to false."
fi

echo "[DEBUG] Resolved flags: IS_API=$IS_API, APPLY_POLICIES=$APPLY_POLICIES, APPLY_SLA=$APPLY_SLA, APPLY_CONTRACTS=$APPLY_CONTRACTS"

# --- Extract RAML coordinates from pom.xml (only if is.api.manager=true) ---
RAML_GROUP_ID=""
RAML_ARTIFACT_ID=""
RAML_VERSION=""

if [[ "$IS_API" == "true" ]]; then
  echo "[DEBUG] is.api.manager=true — searching for RAML dependency in pom.xml"
  POM_FILE=$(find "$EXTRACT_DIR/META-INF/maven" -name "pom.xml" 2>/dev/null | head -1)
  echo "[DEBUG] POM_FILE search result: $POM_FILE"

  if [[ -n "$POM_FILE" && -f "$POM_FILE" ]]; then
    echo "[DEBUG] pom.xml found at: $POM_FILE"
    echo "[DEBUG] === PACKAGED POM.XML CONTENT (start) ==="
    cat "$POM_FILE"
    echo "[DEBUG] === PACKAGED POM.XML CONTENT (end) ==="

    # Find dependency block containing <classifier>raml</classifier> using awk/grep (namespace-agnostic)
    RAML_BLOCK=$(awk '/<dependency>/{block=""} {block=block $0 "\n"} /<\/dependency>/{if (block ~ /<classifier>raml<\/classifier>/) print block}' "$POM_FILE")
    echo "[DEBUG] RAML dependency block: $RAML_BLOCK"

    if [[ -n "$RAML_BLOCK" ]]; then
      RAML_GROUP_ID=$(echo "$RAML_BLOCK" | grep '<groupId>' | sed 's/.*<groupId>\(.*\)<\/groupId>.*/\1/' | tr -d '[:space:]')
      RAML_ARTIFACT_ID=$(echo "$RAML_BLOCK" | grep '<artifactId>' | sed 's/.*<artifactId>\(.*\)<\/artifactId>.*/\1/' | tr -d '[:space:]')
      RAML_VERSION=$(echo "$RAML_BLOCK" | grep '<version>' | sed 's/.*<version>\(.*\)<\/version>.*/\1/' | tr -d '[:space:]')
      echo "RAML dependency found in JAR pom.xml: ${RAML_GROUP_ID}:${RAML_ARTIFACT_ID}:${RAML_VERSION}"
    else
      echo "[DEBUG] No <dependency> with <classifier>raml</classifier> found in packaged pom.xml"
      echo "[DEBUG] Falling back to build-metadata.json..."

      # Fallback: read RAML coords from build-metadata.json (extracted from source pom.xml during Build)
      METADATA_FILE="$(ci_pipeline_workspace)/build-metadata/build-metadata.json"
      if [[ -f "$METADATA_FILE" ]]; then
        echo "[DEBUG] build-metadata.json found. Content:"
        echo "[DEBUG] $(cat "$METADATA_FILE")"
        RAML_GROUP_ID=$(jq -r '.ramlGroupId // empty' "$METADATA_FILE")
        RAML_ARTIFACT_ID=$(jq -r '.ramlArtifactId // empty' "$METADATA_FILE")
        RAML_VERSION=$(jq -r '.ramlVersion // empty' "$METADATA_FILE")

        if [[ -n "$RAML_GROUP_ID" && -n "$RAML_ARTIFACT_ID" ]]; then
          echo "RAML dependency found in build-metadata: ${RAML_GROUP_ID}:${RAML_ARTIFACT_ID}:${RAML_VERSION}"
        else
          echo "[DEBUG] No RAML coordinates in build-metadata.json either"
          ci_log_warning "is.api.manager=true but no RAML dependency found in pom.xml or build-metadata. Skipping API Manager steps."
          IS_API="false"
        fi
      else
        echo "[DEBUG] build-metadata.json NOT found at: $METADATA_FILE"
        ci_log_warning "is.api.manager=true but no RAML dependency found and no build-metadata available. Skipping API Manager steps."
        IS_API="false"
      fi
    fi
  else
    echo "[DEBUG] pom.xml NOT found under META-INF/maven. Listing:"
    echo "[DEBUG] $(find "$EXTRACT_DIR/META-INF" -type f 2>/dev/null | head -20)"
    ci_log_warning "pom.xml not found in extracted JAR."
    IS_API="false"
  fi
else
  echo "[DEBUG] is.api.manager=false — skipping ALL API Manager steps (no RAML read, no token, no instance)"
fi

# --- Resolve env-settings paths for policies/SLA/contracts ---
ENV_COMPONENTS_BASE="${ENV_SETTINGS_PATH}/${APP_NAME}"
POLICIES_PATH="${ENV_COMPONENTS_BASE}/policies"
SLA_PATH="${ENV_COMPONENTS_BASE}/sla-tiers"
CONTRACTS_PATH="${ENV_COMPONENTS_BASE}/contracts"

echo "Env-settings paths:"
echo "  Policies: $POLICIES_PATH (exists=$([ -d "$POLICIES_PATH" ] && echo 'yes' || echo 'no'))"
echo "  SLA Tiers: $SLA_PATH (exists=$([ -d "$SLA_PATH" ] && echo 'yes' || echo 'no'))"
echo "  Contracts: $CONTRACTS_PATH (exists=$([ -d "$CONTRACTS_PATH" ] && echo 'yes' || echo 'no'))"

# --- Set output variables ---
ci_set_var IS_API "$IS_API"
ci_set_var APPLY_POLICIES "$APPLY_POLICIES"
ci_set_var APPLY_SLA "$APPLY_SLA"
ci_set_var APPLY_CONTRACTS "$APPLY_CONTRACTS"
ci_set_var ramlGroupId "$RAML_GROUP_ID"
ci_set_var ramlArtifactId "$RAML_ARTIFACT_ID"
ci_set_var ramlVersion "$RAML_VERSION"
ci_set_var policiesPath "$POLICIES_PATH"
ci_set_var slaTiersPath "$SLA_PATH"
ci_set_var contractsPath "$CONTRACTS_PATH"
echo "[DEBUG] Output variables set:"
echo "[DEBUG]   IS_API=$IS_API"
echo "[DEBUG]   APPLY_POLICIES=$APPLY_POLICIES"
echo "[DEBUG]   APPLY_SLA=$APPLY_SLA"
echo "[DEBUG]   APPLY_CONTRACTS=$APPLY_CONTRACTS"
echo "[DEBUG]   ramlGroupId=$RAML_GROUP_ID"
echo "[DEBUG]   ramlArtifactId=$RAML_ARTIFACT_ID"
echo "[DEBUG]   ramlVersion=$RAML_VERSION"
echo "[DEBUG] CREATE API COMPONENTS - FLAG DETECTION COMPLETE"
# <<< extracted body
